using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so we must opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws in EF Core 9 for Cosmos provider.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: EF Core 9 uses sync-over-async by default for Cosmos.
        // SyncJob calls SaveChanges() synchronously — this still works but now logs a warning.
        // Consider migrating to SaveChangesAsync() for best practice.
        base.OnConfiguring(optionsBuilder);
    }
}

// Breaking change 5: If you have raw SQL like:
//   SELECT * FROM c WHERE c.Discriminator = 'Blog'
// This still works ONLY because we explicitly set .HasDiscriminator<string>("Discriminator") above.
// Without that fix, EF Core 9 would write "$type" and old queries would return no results.

class Blog { public string Id { get; set; } public string Name { get; set; } }

// Preserves legacy "EntityType|Key" id format for existing documents
using Microsoft.EntityFrameworkCore.ValueGeneration;
using Microsoft.EntityFrameworkCore.ChangeTracking;
class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

